  m2[2][4] -= f*m2[0][4];
  f = m2[3][0]/m2[0][0];
  m2[3][0] -= f*m2[0][0];
  m2[3][1] -= f*m2[0][1];
  m2[3][2] -= f*m2[0][2];
  m2[3][3] -= f*m2[0][3];
  m2[3][4] -= f*m2[0][4];
  f = m2[4][0]/m2[0][0];
  m2[4][0] -= f*m2[0][0];
  m2[4][1] -= f*m2[0][1];
  m2[4][2] -= f*m2[0][2];
  m2[4][3] -= f*m2[0][3];
  m2[4][4] -= f*m2[0][4];     // Row 2
  f = m2[2][1]/m2[1][1];
  m2[2][0] -= f*m2[1][0];
  m2[2][1] -= f*m2[1][1];
  m2[2][2] -= f*m2[1][2];
  m2[2][3] -= f*m2[1][3];
  m2[2][4] -= f*m2[1][4];
  f = m2[3][1]/m2[1][1];
