double mat_det5(double m[5][5])
{
  double ref[5][5], diag = 1.0;
  mat_ref5(m,ref);
  diag *= ref[0][0];
  diag *= ref[1][1];
  diag *= ref[2][2];
  diag *= ref[3][3];
  diag *= ref[4][4];
  return diag;
}

